const BASE_URL_TO_PROVIDER: [RegExp, string][] = [
  [/\.azure\.com|azure\.openai\.com|openai\.azure\.com/i, 'azure'],
  [/api\.cerebras\.ai/i, 'cerebras'],
  [/bytepluses\.com|byteplus\.com/i, 'byteplus'],
  [/api\.cloudflare\.com|workers\.ai/i, 'cloudflare workers ai'],
  [/cohere\.ai/i, 'cohere'],
  [/commandcode\.ai/i, 'command code'],
  [/generativelanguage\.googleapis\.com/i, 'gemini'],
  [/models\.inference\.ai\.azure\.com/i, 'github models'],
  [/api\.groq\.com/i, 'groq'],
  [/api\.fireworks\.ai/i, 'fireworks'],
  [/huggingface\.co/i, 'hugging face'],
  [/kilo\.ai/i, 'kilo code'],
  [/integrate\.api\.nvidia\.com/i, 'nvidia nim'],
  [/api\.ollama\.com/i, 'ollama cloud'],
  [/openrouter\.ai/i, 'openrouter'],
  [/api\.pioneer\.ai|pioneer\.ai/i, 'pioneer'],
  [/siliconflow\.cn|api\.siliconflow/i, 'siliconflow'],
  [/aiplatform\.googleapis\.com/i, 'vertex'],
];

const MODEL_NAME_TO_PROVIDER: [RegExp, string][] = [
  [/^@cf\//i, 'cloudflare workers ai'],
  [/^@hf\//i, 'hugging face'],
  [/gemini/i, 'gemini'],
  [/^accounts\/fireworks\/models\//i, 'fireworks'],
  [/^mistral/i, 'mistral ai'],
  [/^nvidia\//i, 'nvidia'],
  [/^qwen\//i, 'qwen'],
  [/^stepfun\//i, 'stepfun'],
  [/^corethink/i, 'corethink'],
];

/**
 * Resolve a logo for a custom provider.
 * Priority: model name (provider prefix) → provider name → base URL → null.
 */
function resolveCustomLogo(name: string, baseUrl?: string, modelName?: string): string | null {
  // Priority 1: infer provider from model name prefix
  if (modelName) {
    for (const [pattern, key] of MODEL_NAME_TO_PROVIDER) {
      if (pattern.test(modelName)) {
        const logo = CUSTOM_PROVIDER_LOGOS[key];
        if (logo) return logo;
        break; // matched but no logo for this provider, fall through
      }
    }
  }
  // Priority 2: provider name
  const byName = CUSTOM_PROVIDER_LOGOS[name.toLowerCase()];
  if (byName) return byName;
  // Priority 3: base URL
  if (baseUrl) {
    for (const [pattern, key] of BASE_URL_TO_PROVIDER) {
      if (pattern.test(baseUrl)) return CUSTOM_PROVIDER_LOGOS[key] ?? null;
    }
  }
  return null;
}

/**
 * Returns an <img> icon for a custom provider if a known logo exists,
 * or null if no logo is available. Matches by name, base URL, or model name.
 *
 * Local-LLM custom providers (LM Studio, Ollama) share a
 * canonical display name across the codebase — we look those up against
 * the shared provider registry first so the branded `providerIcon` is
 * used everywhere, not a letter badge.
 */
export function customProviderLogo(
  name: string,
  size: number = 16,
  baseUrl?: string,
  modelName?: string,
): JSX.Element | null {
  const normalized = normalizeProviderName(name);
  const shared =
    SHARED_PROVIDER_BY_ID_OR_ALIAS.get(normalized) ??
    SHARED_PROVIDER_BY_ID_OR_ALIAS.get(name) ??
    SHARED_PROVIDER_BY_ID_OR_ALIAS.get(name.toLowerCase());
  if (shared) {
    const branded = providerIcon(shared.id, size);
    if (branded) return branded;
  }

  const logo = resolveCustomLogo(name, baseUrl, modelName);
  if (!logo) return null;
  return (
    <img
      src={logo}
      alt={name}
      width={size}
      height={size}
      style={{ display: 'block', 'object-fit': 'contain' }}
    />
  );
}
